    wr16((uint16_t)(Y + 0x1A), D);                   /* LDA53 */
    wr16((uint16_t)(Y + 0x22), D);                   /* LDA56 */
    wr16((uint16_t)(Y + 0x2A), D);                   /* LDA59 */
    D = rd16(BN_SCL);                                /* LDA5C */
    wr16((uint16_t)(Y + 4), D);                      /* LDA5F */
    wr16((uint16_t)(Y + 12), D);                     /* LDA61 */
    wr16((uint16_t)(Y + 0x14), D);                   /* LDA63 */
    wr16((uint16_t)(Y + 0x1C), D);                   /* LDA66 */
